<?php
require_once __DIR__ . '/../config/db.php';
$user=requireLogin('admin');$data=input();$id=(int)($data['reclamation_id']??0);$ref=trim((string)($data['reference']??''));$status=(string)($data['status']??$data['next_status']??'');$action=(string)($data['action']??'validate');
$allowed=['attente','encours','prise_charge','demande_supplementaire','resolu','cloture'];if(!in_array($status,$allowed,true))jsonResponse(['success'=>false,'message'=>'Statut invalide'],422);
$pdo=db();$q=$pdo->prepare($id?'SELECT id,statut FROM reclamations WHERE id=?':'SELECT id,statut FROM reclamations WHERE reference=?');$q->execute([$id?:$ref]);$row=$q->fetch();if(!$row)jsonResponse(['success'=>false,'message'=>'Reclamation introuvable'],404);$id=(int)$row['id'];$previous=$row['statut'];
if($action==='cancel'){$sequence=$allowed;$index=array_search($status,$sequence,true);$current=array_search($previous,$sequence,true);if($index===false||$index>$current||$index===0)jsonResponse(['success'=>false,'message'=>'Annulation non autorisee'],422);$next=$sequence[$index-1];}else{$next=$status;}
$pdo->beginTransaction();try{$pdo->prepare('UPDATE reclamations SET statut=?,statut_label=?,date_modification=NOW() WHERE id=?')->execute([$next,statusLabel($next),$id]);$pdo->prepare('INSERT INTO status_history (reclamation_id,status,action,auteur,role) VALUES (?,?,?,?,?)')->execute([$id,$next,$action==='cancel'?'Statut annule - retour manuel':statusLabel($next),$user['prenom'].' '.$user['nom'],'admin']);$pdo->commit();jsonResponse(['success'=>true,'status'=>$next,'status_label'=>statusLabel($next)]);}catch(Throwable $e){$pdo->rollBack();jsonResponse(['success'=>false,'message'=>'Erreur serveur'],500);}
